if (!requireNamespace("jsonlite", quietly = TRUE)) stop("jsonlite required")
if (!dir.exists("outputs")) dir.create("outputs", recursive = TRUE)

data(iris, package = "datasets")
species_levels <- levels(iris$Species)

py <- jsonlite::read_json("outputs/iris-python.json", simplifyVector = FALSE)
raw <- jsonlite::read_json("outputs/iris-raw.json",   simplifyVector = FALSE)
upstream_source_sha256 <- py[["source_sha256"]]

compute_summary <- function(species_levels) {
  out <- list()
  for (sp in species_levels) {
    idx <- which(iris$Species == sp)
    n <- length(idx)
    out[[sp]] <- list(
      count             = n,
      mean_sepal_length = mean(iris$Sepal.Length[idx]),
      mean_petal_length = mean(iris$Petal.Length[idx]),
      mean_petal_width  = mean(iris$Petal.Width[idx])
    )
  }
  out
}

classify_one <- function(pl, pw) {
  if (pl < 2.5) return("setosa")
  if (pw < 1.8) return("versicolor")
  "virginica"
}

species_summary <- compute_summary(species_levels)

confusion_matrix <- list()
for (sp_true in species_levels) {
  inner <- list()
  for (sp_pred in species_levels) inner[[sp_pred]] <- 0L
  confusion_matrix[[sp_true]] <- inner
}
correct <- 0L
n_total <- nrow(iris)
for (i in seq_len(n_total)) {
  true_sp <- as.character(iris$Species[i])
  pred_sp <- classify_one(iris$Petal.Length[i], iris$Petal.Width[i])
  confusion_matrix[[true_sp]][[pred_sp]] <- confusion_matrix[[true_sp]][[pred_sp]] + 1L
  if (identical(true_sp, pred_sp)) correct <- correct + 1L
}
accuracy <- correct / n_total

max_abs_difference <- 0
for (sp in species_levels) {
  s_py <- py[["species_summary"]][[sp]]
  s_r  <- species_summary[[sp]]
  for (k in c("mean_sepal_length","mean_petal_length","mean_petal_width")) {
    d <- abs(s_py[[k]] - s_r[[k]])
    if (is.na(d)) d <- 0
    if (d > max_abs_difference) max_abs_difference <- d
  }
  if (s_py[["count"]] != s_r[["count"]]) {
    d <- abs(as.numeric(s_py[["count"]]) - as.numeric(s_r[["count"]]))
    if (d > max_abs_difference) max_abs_difference <- d
  }
}
if (abs(as.numeric(py[["accuracy"]]) - accuracy) > max_abs_difference)
  max_abs_difference <- abs(as.numeric(py[["accuracy"]]) - accuracy)

crosscheck_passed <- isTRUE(max_abs_difference <= 1e-12)

out <- list(
  version                 = 1,
  upstream_source_sha256  = upstream_source_sha256,
  species_summary         = species_summary,
  confusion_matrix        = confusion_matrix,
  accuracy                = accuracy,
  max_abs_difference      = max_abs_difference,
  crosscheck_passed       = crosscheck_passed
)

jsonlite::write_json(out, "outputs/iris-crosscheck.json",
                     auto_unbox = TRUE, digits = NA, pretty = TRUE)

verify <- jsonlite::read_json("outputs/iris-crosscheck.json", simplifyVector = FALSE)
cat("max_abs_difference =", verify[["max_abs_difference"]], "\n", sep = "")
cat("crosscheck_passed  =", verify[["crosscheck_passed"]],  "\n", sep = "")
cat("accuracy            =", verify[["accuracy"]],          "\n", sep = "")
cat("upstream_sha256     =", verify[["upstream_source_sha256"]], "\n", sep = "")
cat("species_keys        =", paste(names(verify[["species_summary"]]), collapse = ", "), "\n", sep = "")
